pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: from address, callee address (will be a helper), uint value, and an array length seed
    function testFuzz_property(address from, uint256 v, uint256 lenSeed) public {
        // keep length in a reasonable wide bound but allow zero to be excluded by require in C
        uint256 len = 1 + (lenSeed % 5); // length between 1 and 5 to satisfy require(_tos.length > 0)

        // deploy a benign callee that always succeeds on the expected selector
        CallerResponder responder = new CallerResponder();

        // build tos array of the responder address repeated len times
        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) { tos[i] = address(responder); }

        // Call transfer and capture whether it returned true (call completed)
        bool ok;
        try c.transfer(from, address(responder), tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            // if it reverts, we consider call did not complete; set ok false
            ok = false;
        }

        // General rule: for all admissible inputs where call completes, reference C returns true.
        // We assert that the observed return (ok) is true. The mutant that returns false will fail for some inputs.
        assertTrue(ok);
    }
}

// Minimal helper that accepts the low-level call with the selector and returns successfully.
contract CallerResponder {
    // matches any calldata; always return true-sized data to mimic successful transferFrom
    fallback() external payable {
        // do nothing, succeed
    }
}

