pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz params: from address, address[] tos encoded as bytes to allow fuzzing length/content, and v
    // We can't fuzz an address to be a contract with failing behavior, so deploy a Reverter and pass its address.
    function testFuzz_property(address from, bytes memory tosEncoded, uint256 v) public {
        // Decode tosEncoded into an address[]; if decoding fails or length==0 we bound/assume accordingly
        address[] memory tos;
        if (tosEncoded.length == 0) {
            // ensure at least one element by constructing a single-element array with the reverter
            tos = new address[](1);
        } else {
            // Try decode; if it doesn't decode to address[] of reasonable length, fallback to length 1
            // Keep it simple: interpret tosEncoded as concatenated 20-byte addresses
            uint256 count = tosEncoded.length / 20;
            if (count == 0) {
                tos = new address[](1);
            } else {
                // limit size to avoid OOG in fuzz
                if (count > 20) count = 20;
                tos = new address[](count);
                for (uint i = 0; i < count; i++) {
                    uint256 start = i * 20;
                    bytes20 addrBytes;
                    assembly {
                        addrBytes := mload(add(add(tosEncoded, 0x20), start))
                    }
                    tos[i] = address(addrBytes);
                }
            }
        }

        // Deploy adversarial callee that always reverts on fallback (to distinguish behavior)
        Reverter r = new Reverter();

        // Replace all tos entries with the reverter address for at least one element to trigger external call behavior
        // But keep fuzzing others: ensure at least one is the reverter
        if (tos.length == 0) {
            tos = new address[](1);
        }
        tos[0] = address(r);

        // Ensure _tos.length > 0 as required by contract
        vm.assume(tos.length > 0);

        // Call transfer and capture whether it completes (does not revert)
        bool ok;
        try c.transfer(from, address(r), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // General property: For the reference C, when at least one callee reverts on the low-level call, transfer must revert (so ok==false);
        // The mutant that returns early would return true (ok==true). We assert that the reference's behavior is consistent: it must NOT return true here.
        // This single assert reads c via its transfer call outcome (ok) and will fail on the mutant for some inputs.
        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert");
    }
}

