pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: from address (as actor), value v, and an arbitrary array length selector
    // We cannot fuzz an address to become a contract with code, so we deploy a malicious helper below
    function testFuzz_property(address from, uint256 v, uint8 tosLen) public {
        // Keep domain wide but avoid zero-length _tos which the function rejects
        uint256 len = bound(tosLen, 1, 5);

        // build tos array of length `len`, fill with some addresses (use the fuzzed `from` for variety)
        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) {
            // vary entries using from and i so fuzzer can explore different combinations
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(from, v, i)))));
        }

        // Deploy an adversarial callee that, when transferFrom is invoked via delegatecall,
        // will write to storage slot 0 (which in the mutant will be C's slot 0) so we can detect mutation.
        MaliciousDelegateWriter mal = new MaliciousDelegateWriter();

        // Call transfer on C, passing the malicious contract address as the callee.
        // We wrap in try/catch in case of unexpected revert, but we still observe C after.
        bool ok;
        try c.transfer(from, address(mal), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: on the correct contract, C's storage slot 0 remains untouched by the callee.
        // We observe it via address(c).balance (not relevant) is allowed but we must read a public getter.
        // The original contract has no named public var called `transfer`, but the prompt specified
        // that slot 0 differs; to read slot 0 we rely on a small view helper deployed in the helper
        // is NOT allowed. Instead, we observe behaviour by calling transfer again with a callee that
        // returns normally: the reference will still run and not see mutated state. However the safest
        // and permitted approach is to rely on that the mutated slot 0 would change the behavior of
        // a subsequent delegatecall attempt by the malicious contract — but tests must read c only.
        // We instead exploit that storage slot 0 in C, if altered by delegatecall, will change the
        // return boolean of a follow-up call that tries to call a view that depends on slot 0. The
        // simplest direct observation permitted is to call transfer again with a benign callee and
        // assert it succeeds on the reference for all inputs. The mutant may cause future transfers to
        // revert if its storage overwrite breaks C's invariants. We therefore assert that calling
        // transfer a second time with a benign no-op callee does not revert on the reference for all inputs.

        // Deploy a benign callee that simply implements transferFrom and returns normally.
        BenignCallee okc = new BenignCallee();

        bool ok2;
        try c.transfer(from, address(okc), tos, v) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        // Single assertion: on the correct contract, the second transfer call must succeed for all inputs.
        // The mutant that used delegatecall and allowed the malicious callee to overwrite C's storage may
        // cause the second call to fail for some inputs — the fuzzer can find those.
        assertTrue(ok2);
    }
}

// A malicious contract that, if invoked via delegatecall, will write to storage slot 0.
contract MaliciousDelegateWriter {
    // storage layout irrelevant here; when executed via delegatecall in C, writes affect C's storage
    uint256 public dummy;

    // This mimics transferFrom(address,address,uint256)
    function transferFrom(address, address, uint256) external returns (bool) {
        // write to slot 0
        assembly { sstore(0, 1) }
        return true;
    }
}

// A benign callee that simply returns true on transferFrom
contract BenignCallee {
    function transferFrom(address, address, uint256) external returns (bool) {
        return true;
    }
}

