import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed params: from (actor who should be debited inside callee), amount, and an index to choose how many recipients
    function testFuzz_property(address from, uint256 v, uint8 tosCount) public {
        // keep tosCount reasonable but allow zero check to be handled by require in C
        uint256 n = bound(tosCount, 1, 5); // ensure at least 1 recipient so require(_tos.length > 0) holds

        // Deploy adversarial callee that relies on state modification to succeed
        // This helper will implement transferFrom and will revert unless it can update its internal mapping
        StatefulCallee helper = new StatefulCallee();

        // prepare tos array filled with some recipient addresses (use helper itself as recipient to keep deterministic behavior)
        address[] memory tos = new address[](n);
        for (uint i = 0; i < n; i++) {
            tos[i] = address(this);
        }

        // First: call helper to pre-seed state so that transferFrom can succeed only if state mutation is allowed
        // The helper exposes an entry that when called via a stateful call will set allowance for "from" and recipient
        // We need to perform that setup by calling helper.setAllowance(from, recipient, v)
        // This call must be a normal state-changing external call, which our test can perform
        helper.setAllowance(from, address(this), v);

        // Now invoke c.transfer which will low-level call helper.transferFrom(from, recipient, v)
        // The reference uses call, which allows the callee to perform state changes; the mutant uses staticcall,
        // which prevents those state changes, so the callee's transferFrom will revert or fail because it cannot mutate its mapping

        bool ok;
        try c.transfer(from, address(helper), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal rule: the reference will allow the callee's transferFrom (which requires state writes) to succeed for all admissible inputs;
        // the mutant using staticcall will prevent the state write and can therefore cause the overall call to fail for some inputs.
        // Assert that the call succeeded (the reference must always allow the callee to perform its state change and return true).
        // This single assertion should hold for the reference implementation for all fuzzed inputs, but the mutant (staticcall) will fail for some inputs.
        assertTrue(ok);
    }
}

// Adversarial helper: requires ability to mutate state inside transferFrom to succeed.
contract StatefulCallee {
    // mapping of allowances keyed by (from => (to => amount)) encoded as bytes32
    mapping(bytes32 => uint256) public allowances;

    function key(address a, address b) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked(a, b));
    }

    // Called by the test to set up state precondition. This is a normal external call that mutates state.
    function setAllowance(address from, address to, uint256 v) external {
        allowances[key(from, to)] = v;
    }

    // This is the function selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    // Implemented to require reducing allowance (a state write). If called under staticcall, the state write will revert.
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        bytes32 k = key(from, to);
        uint256 a = allowances[k];
        require(a >= v, "insufficient allowance");
        // perform state-changing update; staticcall would prevent this and cause revert
        allowances[k] = a - v;
        return true;
    }
}

