contract CallerLike {
    uint public counter;

    // Mimic signature transferFrom(address,address,uint256)
    function transferFrom(address /*from*/, address /*to*/, uint256 /*amt*/) external returns (bool) {
        // attempt a state write that will fail under staticcall; under call this succeeds
        counter += 1;
        return true;
    }
