        }

        // The rule: reference contract should revert when any callee reverts; mutant that ignores failures will not.
        // We observe whether c.transfer reverts by try/catch and assert that it returns false (i.e., it reverts) when using the reverting callee.
        bool ok;
        try c.transfer(from, tos[0], tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: when the provided callee reverts, the reference implementation must revert (ok == false).
        // For the non-reverting callee, transfer should succeed (ok == true).
        // This encodes the universal property distinguishing the correct vs buggy mutant.
        if (useRevertingCallee) {
            assertTrue(!ok);
        } else {
            assertTrue(ok);
        }
    }
}

